REVOKE ALL ON FUNCTION public.record_viewer_presence(uuid,uuid,text,text,text,text,text,text,jsonb,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.record_viewer_presence(uuid,uuid,text,text,text,text,text,text,jsonb,text,uuid) TO service_role;